from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox']);page=b.new_page(viewport={'width':1440,'height':1000});page.goto('http://localhost:5173/#/login/admin');page.get_by_role('button',name='EN',exact=True).click();page.get_by_role('button',name='Enter demo workspace').click();page.get_by_role('button',name='Courses & groups',exact=True).click();page.locator('.group-card').filter(has=page.get_by_role('heading',name='TOEFL Advanced',exact=True)).get_by_role('button',name='View group',exact=True).click();assert page.locator('select').input_value()=='g4';assert page.locator('tbody tr').count()==3
 page.get_by_role('button',name='Sign out',exact=True).click();page.get_by_role('button',name='Teacher workspace',exact=True).click();page.get_by_role('button',name='Enter demo workspace').click();page.get_by_role('button',name='My groups',exact=True).click();page.locator('.group-card').filter(has=page.get_by_role('heading',name='TOEFL Advanced',exact=True)).get_by_role('button',name='View students',exact=True).click();assert page.locator('select').input_value()=='g4';assert page.locator('tbody tr').count()==3
 page.locator('select').select_option('all');page.get_by_role('button',name='Attendance',exact=True).click();assert page.locator('select').input_value()=='g1';page.get_by_role('button',name='Save attendance',exact=True).click();assert page.get_by_text('Saved',exact=True).is_visible();print('PASS: group filters survive navigation in admin and teacher panels; attendance handles All groups → IELTS correctly.');b.close()
